var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
var app = builder.Build();

app.Use(async (context, next) =>
{
    // runs before authentication: no token has been read yet
    var user = context.User.Identity?.Name ?? "anonymous";
    app.Logger.LogInformation("{User} -> {Path}", user, context.Request.Path);
    await next(context);
});
app.UseAuthentication();
app.UseAuthorization();

app.MapGet("/orders", () => "orders").RequireAuthorization();
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
var app = builder.Build();

app.UseAuthentication(); // reads the token and sets context.User
app.Use(async (context, next) =>
{
    // before authorization, so rejected calls are logged too
    var user = context.User.Identity?.Name ?? "anonymous";
    app.Logger.LogInformation("{User} -> {Path}", user, context.Request.Path);
    await next(context);
});
app.UseAuthorization();

app.MapGet("/orders", () => "orders").RequireAuthorization();
app.Run();
